contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address who, uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(who != address(this), "self-call would trigger receive");
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "not enough balance");

        uint contractBalanceBefore = address(c).balance;
        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(who); if (__ESBMC_reverted()) return;

        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(who); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;

        assert(balanceAfter - balanceBefore + (contractBalanceAfter - contractBalanceBefore) == amount);
    }
}

