pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address who, uint256 lockTime, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(who != address(this));
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint contractBalanceBefore = address(c).balance;
        uint256 unlockTimeBefore;
        uint256 balanceBefore;
        try c.Acc(who) returns (uint256 __r0, uint256 __r1) { unlockTimeBefore = __r0; balanceBefore = __r1; } catch { return; }
        try c.Put{value: amount}(lockTime) {} catch { return; }
        uint256 unlockTimeAfter;
        uint256 balanceAfter;
        try c.Acc(who) returns (uint256 __r0, uint256 __r1) { unlockTimeAfter = __r0; balanceAfter = __r1; } catch { return; }
        uint contractBalanceAfter = address(c).balance;
        assertTrue(balanceAfter - balanceBefore + (contractBalanceAfter - contractBalanceBefore) == amount);
    }

    function testFuzz_run(address who, uint256 lockTime, uint256 amount) public {
        vm.assume(who.code.length == 0 && uint160(who) > 0xffff && who != address(this) && who != address(c) && who != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && who != 0x000000000000000000636F6e736F6c652e6c6f67 && who != 0x4e59b44847b379578588920cA78FbF26c0B4956C && who != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(who, lockTime, amount);
    }

    receive() external payable {}
}
